from abc import ABC, abstractmethod
from dataclasses import dataclass

# ===== Abstraction layer 1: payment gateway interface =====
class PaymentGateway(ABC):
    """Contract every payment provider must implement."""
    @abstractmethod
    def charge(self, amount_cents: int, currency: str) -> str:
        """Charge a card; returns provider transaction id."""
        ...

    @abstractmethod
    def refund(self, transaction_id: str) -> bool:
        ...


# ===== Abstraction layer 2: concrete implementations =====
class StripeGateway(PaymentGateway):
    def __init__(self, api_key: str):
        self._api_key = api_key

    def charge(self, amount_cents: int, currency: str) -> str:
        # ... stripe-specific HTTP call ...
        return f"stripe-{amount_cents}"

    def refund(self, transaction_id: str) -> bool:
        return True


class PayPalGateway(PaymentGateway):
    def __init__(self, client_id: str, secret: str):
        self._client_id = client_id
        self._secret = secret

    def charge(self, amount_cents: int, currency: str) -> str:
        # ... paypal-specific HTTP call ...
        return f"paypal-{amount_cents}"

    def refund(self, transaction_id: str) -> bool:
        return True


# ===== Abstraction layer 3: business facade =====
class PaymentService:
    """Higher-level API used by callers; hides provider specifics."""
    def __init__(self, gateway: PaymentGateway):
        self._gateway = gateway

    def pay(self, order_id: str, amount_cents: int, currency: str) -> str:
        tx = self._gateway.charge(amount_cents, currency)
        return f"{order_id}:{tx}"

    def refund_order(self, order_id: str, tx_id: str) -> bool:
        return self._gateway.refund(tx_id)


# ===== Caller (never touches gateway details) =====
class CheckoutController:
    def __init__(self, service: PaymentService):
        self._service = service

    def checkout(self, order_id: str, total_cents: int):
        return self._service.pay(order_id, total_cents, "USD")

from abc import ABC, abstractmethod
from typing import Optional

# ===== Abstraction layer 1: repository contract =====
class UserRepository(ABC):
    @abstractmethod
    def find_by_email(self, email: str) -> Optional[dict]:
        ...

    @abstractmethod
    def save(self, user: dict) -> None:
        ...


# ===== Abstraction layer 2: SQL implementation =====
class SqlUserRepository(UserRepository):
    def __init__(self, conn):
        self._conn = conn

    def find_by_email(self, email: str) -> Optional[dict]:
        row = self._conn.execute(
            "SELECT * FROM users WHERE email = ?", (email,)
        ).fetchone()
        return dict(row) if row else None

    def save(self, user: dict) -> None:
        self._conn.execute(
            "INSERT INTO users (email, name) VALUES (?, ?)",
            (user["email"], user["name"]),
        )
        self._conn.commit()


# ===== Abstraction layer 3: application service =====
class UserService:
    """Business logic; must stay storage-agnostic."""
    def __init__(self, repo: UserRepository):
        self._repo = repo

    def register(self, email: str, name: str) -> dict:
        if self._repo.find_by_email(email):
            raise ValueError(f"user exists: {email}")
        user = {"email": email, "name": name}
        self._repo.save(user)
        return user


# ===== wiring =====
def build_service(conn) -> UserService:
    return UserService(SqlUserRepository(conn))

from abc import ABC, abstractmethod
from typing import Any, Callable

# ===== Abstraction layer 1: event contract =====
@dataclass
class Event:
    type: str
    payload: dict


# ===== Abstraction layer 2: bus (core infrastructure) =====
class EventBus:
    """Core dispatch loop. Handlers register by event type; bus routes events."""
    def __init__(self):
        self._handlers: dict[str, list[Callable[[Event], None]]] = {}

    def subscribe(self, event_type: str, handler: Callable[[Event], None]) -> None:
        self._handlers.setdefault(event_type, []).append(handler)

    def publish(self, event: Event) -> None:
        for handler in self._handlers.get(event.type, []):
            handler(event)


# ===== Abstraction layer 3: concrete handlers =====
class EmailNotifier:
    def handle_user_registered(self, event: Event) -> None:
        # send welcome email from event.payload
        pass


class AuditLogger:
    def handle_user_registered(self, event: Event) -> None:
        # write audit line from event.payload
        pass


# ===== wiring =====
def wire(bus: EventBus) -> None:
    notifier = EmailNotifier()
    logger = AuditLogger()
    bus.subscribe("user.registered", notifier.handle_user_registered)
    bus.subscribe("user.registered", logger.handle_user_registered)
